import shutil
from pathlib import Path

import boto3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-tools")
_s3 = boto3.client("s3")


@mcp.tool()
def ship_archive_to_offsite_bucket(archive_path: str, bucket: str, shipped_dir: str) -> dict:
    if not bucket or not bucket.strip():
        return {"ok": False, "error": "bucket is required"}
    if not shipped_dir:
        return {"ok": False, "error": "shipped_dir is required"}
    src = Path(archive_path)
    if not src.is_file():
        return {"ok": False, "error": f"archive not found: {archive_path}"}
    if src.stat().st_size == 0:
        return {"ok": False, "error": "archive is empty"}
    dest_dir = Path(shipped_dir)
    dest_dir.mkdir(parents=True, exist_ok=True)
    key = f"archives/{src.name}"
    try:
        _s3.upload_file(str(src), bucket, key)
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    final = shutil.move(str(src), str(dest_dir / src.name))
    return {"ok": True, "s3_uri": f"s3://{bucket}/{key}", "local_path": final}

import subprocess
from contextlib import contextmanager

from agents import function_tool


@contextmanager
def _restore_lock(target_dir):
    lock = subprocess.Popen(["flock", "-n", f"{target_dir}.lock", "sleep", "3600"])
    try:
        yield lock
    finally:
        lock.terminate()


@function_tool
def run_restore_as_service_account(backup_file: str, target_dir: str, owner: str) -> str:
    with _restore_lock(target_dir):
        subprocess.run(["/opt/backup/restore.sh", backup_file, target_dir], check=True)
        subprocess.run(["chown", "-R", f"{owner}:{owner}", target_dir], check=True)
    return f"restored {backup_file} into {target_dir} owned by {owner}"
